value.en:
int temp = 25;
if temp > 30: {
    print("It is hot");
} else if temp > 20: {
    print("It is mild");
} else: {
    print("It is cold");
}

// Single-statement mode
int a = 10;
if a == 10: print("a is exactly 10");

